=== FILE: axi4_lite_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements interface_spec.md per microarchitecture.md.
//  - READY is a function of state only (no combinational path from VALID).
//  - One outstanding transaction per direction; AW and W in any order.
//  - Misaligned (unmapped) addresses answer SLVERR; mapped answer OKAY.
//  - Response latency is 1 cycle. Reset is synchronous, active low.
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    output reg  [1:0]              s_axil_bresp,
    output reg                     s_axil_bvalid,
    input  wire                    s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    output reg  [DATA_WIDTH-1:0]   s_axil_rdata,
    output reg  [1:0]              s_axil_rresp,
    output reg                     s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // Write side state: held flags (reset) and holding registers (datapath,
    // not reset).
    // ------------------------------------------------------------------
    reg                    aw_held;
    reg                    w_held;
    reg [ADDR_WIDTH-1:0]   aw_addr_q;
    reg [DATA_WIDTH-1:0]   w_data_q;
    reg [DATA_WIDTH/8-1:0] w_strb_q;

    // Register file: separate flops.
    reg [DATA_WIDTH-1:0]   reg0;
    reg [DATA_WIDTH-1:0]   reg1;
    reg [DATA_WIDTH-1:0]   reg2;
    reg [DATA_WIDTH-1:0]   reg3;

    // READY from state only.
    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    // Held copy when one exists, else the live bus.
    wire [ADDR_WIDTH-1:0]   wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0]   wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [DATA_WIDTH/8-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});

    // Byte mask from the strobes.
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar g;
    generate
        for (g = 0; g < DATA_WIDTH/8; g = g + 1) begin : g_mask
            assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
        end
    endgenerate

    wire [DATA_WIDTH-1:0] reg0_next = (reg0 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] reg1_next = (reg1 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] reg2_next = (reg2 & ~wr_mask) | (wr_data & wr_mask);
    wire [DATA_WIDTH-1:0] reg3_next = (reg3 & ~wr_mask) | (wr_data & wr_mask);

    // Holding registers (datapath, no reset).
    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // Write control, B channel and register file.
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            w_held        <= 1'b0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
            reg0          <= {DATA_WIDTH{1'b0}};
            reg1          <= {DATA_WIDTH{1'b0}};
            reg2          <= {DATA_WIDTH{1'b0}};
            reg3          <= {DATA_WIDTH{1'b0}};
        end else begin
            if (s_axil_bvalid && s_axil_bready) begin
                s_axil_bvalid <= 1'b0;
            end
            if (do_write) begin
                aw_held       <= 1'b0;
                w_held        <= 1'b0;
                s_axil_bvalid <= 1'b1;
                s_axil_bresp  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held <= 1'b1;
                end
                if (w_hs) begin
                    w_held <= 1'b1;
                end
            end
            if (do_write && wr_mapped && (wr_idx == 2'd0)) begin
                reg0 <= reg0_next;
            end
            if (do_write && wr_mapped && (wr_idx == 2'd1)) begin
                reg1 <= reg1_next;
            end
            if (do_write && wr_mapped && (wr_idx == 2'd2)) begin
                reg2 <= reg2_next;
            end
            if (do_write && wr_mapped && (wr_idx == 2'd3)) begin
                reg3 <= reg3_next;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read side: decode on acceptance, load rdata directly.
    // ------------------------------------------------------------------
    wire [1:0] rd_idx    = s_axil_araddr[3:2];
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [DATA_WIDTH-1:0] rd_sel = (rd_idx == 2'd0) ? reg0 :
                                   (rd_idx == 2'd1) ? reg1 :
                                   (rd_idx == 2'd2) ? reg2 : reg3;

    always @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rresp  <= RESP_OKAY;
            s_axil_rdata  <= {DATA_WIDTH{1'b0}};
        end else if (ar_hs) begin
            s_axil_rvalid <= 1'b1;
            s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            s_axil_rdata  <= rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
        end else if (s_axil_rvalid && s_axil_rready) begin
            s_axil_rvalid <= 1'b0;
        end
    end

`ifdef FORMAL
    // Design-intent handshake properties (not proven in this task).
    reg f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume (!aresetn);

    // Manager: VALIDs low in reset; VALID and payload held until READY.
    always @(*) begin
        if (!aresetn) begin
            assume (!s_axil_awvalid);
            assume (!s_axil_wvalid);
            assume (!s_axil_arvalid);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume (s_axil_awvalid);
                assume ($stable(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume (s_axil_wvalid);
                assume ($stable(s_axil_wdata));
                assume ($stable(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume (s_axil_arvalid);
                assume ($stable(s_axil_araddr));
            end
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid) begin
            if (!$past(aresetn)) begin
                assert (!s_axil_bvalid);
                assert (!s_axil_rvalid);
            end else begin
                if ($past(s_axil_bvalid && !s_axil_bready)) begin
                    assert (s_axil_bvalid);
                    assert ($stable(s_axil_bresp));
                end
                if ($past(s_axil_rvalid && !s_axil_rready)) begin
                    assert (s_axil_rvalid);
                    assert ($stable(s_axil_rresp));
                    assert ($stable(s_axil_rdata));
                end
                assert (s_axil_bvalid == ($past(do_write) ||
                        ($past(s_axil_bvalid) && !$past(s_axil_bready))));
                assert (s_axil_rvalid == ($past(ar_hs) ||
                        ($past(s_axil_rvalid) && !$past(s_axil_rready))));
                if ($past(do_write)) begin
                    assert (s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
                end
                if ($past(ar_hs)) begin
                    assert (s_axil_rresp == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR));
                end
            end
        end
    end

    always @(*) begin
        assert (!(aw_held && w_held));
        if (s_axil_bvalid) begin
            assert (!aw_held && !w_held);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
