`timescale 1ns/1ps
`default_nettype none

`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error msg; end end

// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven after the falling edge; handshakes are sampled before
// the rising edge (READY depends only on state, which changes on rising edges).
module axi4_lite_regs_tb;

    reg         aclk    = 1'b0;
    reg         aresetn = 1'b0;
    reg  [3:0]  awaddr  = 4'h0;
    reg         awvalid = 1'b0;
    wire        awready;
    reg  [31:0] wdata   = 32'h0;
    reg  [3:0]  wstrb   = 4'h0;
    reg         wvalid  = 1'b0;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    reg         bready  = 1'b0;
    reg  [3:0]  araddr  = 4'h0;
    reg         arvalid = 1'b0;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    reg         rready  = 1'b0;

    integer passed = 0;
    integer failed = 0;
    reg [8*64-1:0] nonce = {(8*64){1'b0}};
    reg [31:0] model [0:3];

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    axi4_lite_regs #(.ADDR_WIDTH(4), .DATA_WIDTH(32)) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready)
    );

    always #5 aclk = ~aclk;

    function is_mapped_tb(input [3:0] a);
        begin
            is_mapped_tb = (a[1:0] == 2'b00);
        end
    endfunction

    function [31:0] merge_tb(input [31:0] old, input [31:0] d, input [3:0] s);
        begin
            merge_tb[7:0]   = s[0] ? d[7:0]   : old[7:0];
            merge_tb[15:8]  = s[1] ? d[15:8]  : old[15:8];
            merge_tb[23:16] = s[2] ? d[23:16] : old[23:16];
            merge_tb[31:24] = s[3] ? d[31:24] : old[31:24];
        end
    endfunction

    // One write: AW after aw_dly cycles, W after w_dly cycles, BREADY held
    // low for b_dly cycles after BVALID rises.
    task automatic axi_write(input [3:0] addr, input [31:0] data, input [3:0] strb,
                             input integer aw_dly, input integer w_dly, input integer b_dly);
        integer t;
        integer done_t;
        integer bv_t;
        reg aw_done;
        reg w_done;
        reg b_done;
        reg lat_err;
        reg [1:0] exp_resp;
        reg [1:0] held_resp;
        begin
            exp_resp  = is_mapped_tb(addr) ? OKAY : SLVERR;
            t         = 0;
            done_t    = -1;
            bv_t      = -1;
            aw_done   = 1'b0;
            w_done    = 1'b0;
            b_done    = 1'b0;
            lat_err   = 1'b0;
            held_resp = 2'b00;
            while (!b_done && t < 64) begin
                @(negedge aclk);
                // Observe B (stable since the last rising edge).
                if (bvalid) begin
                    `CHECK(!awready && !wready, ("write 0x%h: AWREADY or WREADY high while a response is pending", addr))
                    if (bv_t < 0) begin
                        bv_t      = t;
                        held_resp = bresp;
                        `CHECK(done_t >= 0, ("write 0x%h: BVALID rose before AW and W were both accepted", addr))
                        `CHECK(done_t < 0 || ((bv_t - done_t) >= 1 && (bv_t - done_t) <= 2), ("write 0x%h: BVALID latency %0d cycles exceeds the bound of 2", addr, bv_t - done_t))
                        `CHECK(bresp == exp_resp, ("write 0x%h: BRESP %b but expected %b", addr, bresp, exp_resp))
                    end else begin
                        `CHECK(bresp == held_resp, ("write 0x%h: BRESP changed while BVALID waited", addr))
                    end
                end else if (bv_t >= 0) begin
                    failed = failed + 1;
                    $error("write 0x%h: BVALID dropped before it was taken", addr);
                end
                if (done_t >= 0 && bv_t < 0 && !lat_err && (t - done_t) > 2) begin
                    failed  = failed + 1;
                    lat_err = 1'b1;
                    $error("write 0x%h: no BVALID within 2 cycles of the request", addr);
                end
                // Drive.
                if (!aw_done && t >= aw_dly) begin
                    awvalid = 1'b1;
                    awaddr  = addr;
                end else begin
                    awvalid = 1'b0;
                end
                if (!w_done && t >= w_dly) begin
                    wvalid = 1'b1;
                    wdata  = data;
                    wstrb  = strb;
                end else begin
                    wvalid = 1'b0;
                end
                bready = (bv_t >= 0) && (t >= bv_t + b_dly);
                #1;
                // Handshakes that will occur on the coming rising edge.
                if (awvalid) begin
                    `CHECK(awready, ("write 0x%h: AWREADY low with no write response pending", addr))
                    if (awready) aw_done = 1'b1;
                end
                if (wvalid) begin
                    `CHECK(wready, ("write 0x%h: WREADY low with no write response pending", addr))
                    if (wready) w_done = 1'b1;
                end
                if (done_t < 0 && aw_done && w_done) done_t = t;
                if (bvalid && bready) b_done = 1'b1;
                t = t + 1;
            end
            if (!b_done) begin
                failed = failed + 1;
                $error("write 0x%h: transaction timed out", addr);
            end else if (exp_resp == OKAY) begin
                model[addr[3:2]] = merge_tb(model[addr[3:2]], data, strb);
            end
        end
    endtask

    // One read: AR after ar_dly cycles, RREADY held low for r_dly cycles
    // after RVALID rises.
    task automatic axi_read(input [3:0] addr, input integer ar_dly, input integer r_dly);
        integer t;
        integer done_t;
        integer rv_t;
        reg ar_done;
        reg r_done;
        reg lat_err;
        reg [1:0]  exp_resp;
        reg [31:0] exp_data;
        reg [1:0]  held_resp;
        reg [31:0] held_data;
        begin
            exp_resp  = is_mapped_tb(addr) ? OKAY : SLVERR;
            exp_data  = is_mapped_tb(addr) ? model[addr[3:2]] : 32'h0;
            t         = 0;
            done_t    = -1;
            rv_t      = -1;
            ar_done   = 1'b0;
            r_done    = 1'b0;
            lat_err   = 1'b0;
            held_resp = 2'b00;
            held_data = 32'h0;
            while (!r_done && t < 64) begin
                @(negedge aclk);
                if (rvalid) begin
                    `CHECK(!arready, ("read 0x%h: ARREADY high while read data is pending", addr))
                    if (rv_t < 0) begin
                        rv_t      = t;
                        held_resp = rresp;
                        held_data = rdata;
                        `CHECK(done_t >= 0, ("read 0x%h: RVALID rose before AR was accepted", addr))
                        `CHECK(done_t < 0 || ((rv_t - done_t) >= 1 && (rv_t - done_t) <= 2), ("read 0x%h: RVALID latency %0d cycles exceeds the bound of 2", addr, rv_t - done_t))
                        `CHECK(rresp == exp_resp, ("read 0x%h: RRESP %b but expected %b", addr, rresp, exp_resp))
                        `CHECK(rdata == exp_data, ("read 0x%h: RDATA 0x%h but expected 0x%h", addr, rdata, exp_data))
                    end else begin
                        `CHECK(rresp == held_resp && rdata == held_data, ("read 0x%h: RRESP or RDATA changed while RVALID waited", addr))
                    end
                end else if (rv_t >= 0) begin
                    failed = failed + 1;
                    $error("read 0x%h: RVALID dropped before it was taken", addr);
                end
                if (done_t >= 0 && rv_t < 0 && !lat_err && (t - done_t) > 2) begin
                    failed  = failed + 1;
                    lat_err = 1'b1;
                    $error("read 0x%h: no RVALID within 2 cycles of the request", addr);
                end
                if (!ar_done && t >= ar_dly) begin
                    arvalid = 1'b1;
                    araddr  = addr;
                end else begin
                    arvalid = 1'b0;
                end
                rready = (rv_t >= 0) && (t >= rv_t + r_dly);
                #1;
                if (arvalid) begin
                    `CHECK(arready, ("read 0x%h: ARREADY low with no read data pending", addr))
                    if (arready) ar_done = 1'b1;
                end
                if (done_t < 0 && ar_done) done_t = t;
                if (rvalid && rready) r_done = 1'b1;
                t = t + 1;
            end
            if (!r_done) begin
                failed = failed + 1;
                $error("read 0x%h: transaction timed out", addr);
            end
        end
    endtask

    task automatic model_reset;
        begin
            model[0] = 32'h0;
            model[1] = 32'h0;
            model[2] = 32'h0;
            model[3] = 32'h0;
        end
    endtask

    task automatic read_all;
        begin
            axi_read(4'h0, 0, 0);
            axi_read(4'h4, 0, 0);
            axi_read(4'h8, 0, 0);
            axi_read(4'hC, 0, 0);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
        model_reset;

        // ---------------- Reset ----------------
        aresetn = 1'b0;
        repeat (3) @(negedge aclk);
        `CHECK(!bvalid && !rvalid, ("reset: BVALID or RVALID high during reset"))
        aresetn = 1'b1;
        @(negedge aclk);
        `CHECK(awready && wready && arready, ("reset: a READY is low after reset"))
        `CHECK(!bvalid && !rvalid, ("reset: a response is valid after reset with no request"))
        read_all;   // reset values are zero

        // ---------------- Write then read every register ----------------
        axi_write(4'h0, 32'hDEADBEEF, 4'hF, 0, 0, 0);
        axi_write(4'h4, 32'h12345678, 4'hF, 0, 0, 0);
        axi_write(4'h8, 32'hA5A55A5A, 4'hF, 0, 0, 0);
        axi_write(4'hC, 32'h0BADF00D, 4'hF, 0, 0, 0);
        read_all;

        // ---------------- WSTRB partial writes ----------------
        axi_write(4'h0, 32'h11223344, 4'hF, 0, 0, 0);
        axi_write(4'h0, 32'hAABBCCDD, 4'b0101, 0, 0, 0);
        `CHECK(model[0] == 32'h11BB33DD, ("model: REG0 expected 0x11BB33DD after strobe 0101"))
        axi_read(4'h0, 0, 0);
        axi_write(4'h4, 32'hFFFFFFFF, 4'b0000, 0, 0, 0);   // no bytes, still OKAY
        `CHECK(model[1] == 32'h12345678, ("model: REG1 changed by an all-zero strobe"))
        axi_read(4'h4, 0, 0);
        axi_write(4'h8, 32'h99000000, 4'b1000, 0, 0, 0);
        axi_write(4'h8, 32'h00007700, 4'b0010, 0, 0, 0);
        axi_read(4'h8, 0, 0);

        // ---------------- AW/W ordering ----------------
        axi_write(4'h4, 32'hC0FFEE01, 4'hF, 0, 3, 0);   // AW before W
        axi_read(4'h4, 0, 0);
        axi_write(4'h8, 32'hC0FFEE02, 4'hF, 3, 0, 0);   // W before AW
        axi_read(4'h8, 0, 0);
        axi_write(4'hC, 32'hC0FFEE03, 4'hF, 0, 0, 0);   // together
        axi_read(4'hC, 0, 0);
        axi_write(4'h0, 32'hC0FFEE04, 4'hF, 1, 0, 0);   // W one cycle ahead
        axi_write(4'h0, 32'h0000AA00, 4'b0010, 0, 1, 0); // AW one cycle ahead, partial
        axi_read(4'h0, 0, 0);

        // ---------------- B and R backpressure ----------------
        axi_write(4'hC, 32'h5EED5EED, 4'hF, 0, 0, 4);
        axi_write(4'h4, 32'h0F0F0F0F, 4'hF, 2, 1, 3);
        axi_read(4'hC, 0, 5);
        axi_read(4'h4, 2, 3);

        // ---------------- Back-to-back ----------------
        axi_write(4'h0, 32'h00000001, 4'hF, 0, 0, 0);
        axi_write(4'h4, 32'h00000002, 4'hF, 0, 0, 0);
        axi_write(4'h8, 32'h00000003, 4'hF, 0, 0, 0);
        axi_write(4'hC, 32'h00000004, 4'hF, 0, 0, 0);
        axi_read(4'h0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_read(4'hC, 0, 0);
        axi_read(4'h0, 0, 0);

        // ---------------- SLVERR policy ----------------
        axi_write(4'h5, 32'hFFFFFFFF, 4'hF, 0, 0, 0);   // misaligned, REG1 untouched
        axi_write(4'hE, 32'hFFFFFFFF, 4'hF, 0, 0, 2);
        axi_write(4'h2, 32'hFFFFFFFF, 4'hF, 2, 0, 0);
        axi_write(4'h9, 32'hFFFFFFFF, 4'hF, 0, 2, 0);
        read_all;                                       // nothing changed
        axi_read(4'h5, 0, 0);
        axi_read(4'hE, 0, 2);
        axi_read(4'h3, 1, 0);
        axi_read(4'h1, 0, 0);

        // ---------------- Reset discards a half write and clears registers ----------------
        axi_write(4'h0, 32'hAAAA0000, 4'hF, 0, 0, 0);   // ensure all registers nonzero
        @(negedge aclk);
        awaddr  = 4'h4;
        awvalid = 1'b1;
        #1;
        `CHECK(awready, ("reset test: AWREADY low before the lone AW"))
        @(negedge aclk);
        awvalid = 1'b0;
        `CHECK(!bvalid, ("reset test: BVALID rose after AW alone"))
        aresetn = 1'b0;
        repeat (2) @(negedge aclk);
        `CHECK(!bvalid && !rvalid, ("reset test: response valid during reset"))
        aresetn = 1'b1;
        model_reset;
        read_all;                                       // all registers back to zero
        axi_write(4'h8, 32'hCAFEF00D, 4'hF, 3, 0, 0);   // W first: stale AW would misfire
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);

        // Lone W before reset, then an AW-first write.
        @(negedge aclk);
        wdata  = 32'h77777777;
        wstrb  = 4'hF;
        wvalid = 1'b1;
        #1;
        `CHECK(wready, ("reset test: WREADY low before the lone W"))
        @(negedge aclk);
        wvalid = 1'b0;
        `CHECK(!bvalid, ("reset test: BVALID rose after W alone"))
        aresetn = 1'b0;
        repeat (2) @(negedge aclk);
        aresetn = 1'b1;
        model_reset;
        axi_write(4'hC, 32'h13579BDF, 4'hF, 0, 3, 0);   // AW first: stale W would misfire
        read_all;

        repeat (2) @(negedge aclk);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run still ends with a (failing) verdict.
    initial begin
        #200000;
        $error("watchdog: simulation did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

endmodule

`default_nettype wire
